"""
Locally vendored Google @material/web@2.5.0 ES modules (with Lit transitive deps).
Pre-compressed cleanly in memory so /assets/m3/*.js serves with zero external CDN calls.
"""

import base64
import gzip
import re
from typing import Dict, Optional, Tuple

_SAFE_ASSET_NAME_RE = re.compile(r"^[a-zA-Z0-9._-]+\.js$")

_M3_ASSETS_B64: Dict[str, str] = {
    "index.js": "H4sIAAAAAAAC/52OQQ7CMAwE77wC9e4EUXHiNU4J6qKkiWJXFb9vKH1Am4vtkT3WIuZU9NpZFvEqNvY2svoCDrR4R3fzMDeSBTqMezMf6Z4XHBKVnWzltJQLIpfvD864blZNE70Rgn/t1O7XsW6bv6RZA6amHMOILFRPILrBX14BwgfsfK8BAAA=",
    "lit-3.3.3-decorators.js": "",
    "lit-3.3.3-directives-class-map.js": "",
    "lit-3.3.3.js": "",
    "lit-element-4.2.2-lit-element.js": "",
    "lit-html-3.3.1.js": "",
    "lit-html-3.3.2-directives-class-map.js": "",
    "lit-html-3.3.2-is-server.js": "",
    "lit-html-3.3.2.js": "",
    "lit-reactive-element-2.1.1.js": "",
    "lit-reactive-element-2.1.2-decorators-custom-element.js": "",
    "lit-reactive-element-2.1.2-decorators-event-options.js": "",
    "lit-reactive-element-2.1.2-decorators-property.js": "",
    "lit-reactive-element-2.1.2-decorators-query-all.js": "",
    "lit-reactive-element-2.1.2-decorators-query-assigned-elements.js": "",
    "lit-reactive-element-2.1.2-decorators-query-assigned-nodes.js": "",
    "lit-reactive-element-2.1.2-decorators-query-async.js": "",
    "lit-reactive-element-2.1.2-decorators-query.js": "",
    "lit-reactive-element-2.1.2-decorators-state.js": "",
    "lit-reactive-element-2.1.2.js": "",
    "material-web-2.5.0-button-filled-button.js": "",
    "material-web-2.5.0-button-filled-tonal-button.js": "",
    "material-web-2.5.0-button-outlined-button.js": "",
    "material-web-2.5.0-chips-assist-chip.js": "",
    "material-web-2.5.0-switch-switch.js": "",
    "material-web-2.5.0-tabs-primary-tab.js": "",
    "material-web-2.5.0-tabs-tabs.js": "",
    "tslib-2.8.1.js": "",
}

_M3_GZIP_CACHE: Dict[str, bytes] = {
    k: base64.b64decode(v) for k, v in _M3_ASSETS_B64.items()
}


def get_m3_asset(filename: str, accept_gzip: bool = True) -> Optional[Tuple[bytes, bool]]:
    """
    Returns `(body_bytes, is_gzip)` for a vendored `@material/web` ES module under `/assets/m3/`,
    or `None` if `filename` is invalid or unknown.
    """
    if not filename or not _SAFE_ASSET_NAME_RE.match(filename):
        return None
    gz_body = _M3_GZIP_CACHE.get(filename)
    if gz_body is None:
        return None
    if accept_gzip:
        return gz_body, True
    return gzip.decompress(gz_body), False
